void subseq(vector<int>& a, int i, vector<int>& cur, vector<vector<int>>& out) {
    if (i == (int)a.size()) { out.push_back(cur); return; }
    cur.push_back(a[i]);          // pick
    subseq(a, i + 1, cur, out);
    cur.pop_back();               // skip (backtrack)
    subseq(a, i + 1, cur, out);
}

long long power(long long x, long long n) {
    if (n == 0) return 1;
    long long half = power(x, n / 2);
    return (n % 2) ? half * half * x : half * half;
}

void backtrack(State& s, vector<Solution>& out) {
    if (isGoal(s)) { out.push_back(extract(s)); return; }
    for (auto& choice : choices(s)) {
        apply(s, choice);        // try
        backtrack(s, out);       // recurse
        undo(s, choice);         // un-try
    }
}

bool safe(vector<int>& col, int r, int c) {
    for (int i = 0; i < r; i++)
        if (col[i] == c || abs(col[i]-c) == abs(i-r)) return false;
    return true;
}
void solve(int r, int n, vector<int>& col, int& count) {
    if (r == n) { count++; return; }
    for (int c = 0; c < n; c++)
        if (safe(col, r, c)) {
            col[r] = c;          // place
            solve(r+1, n, col, count);
            col[r] = -1;         // remove (backtrack)
        }
}

void merge(vector<int>& a, int l, int m, int r) {
    vector<int> tmp;
    int i = l, j = m + 1;
    while (i <= m && j <= r)
        tmp.push_back(a[i] <= a[j] ? a[i++] : a[j++]);
    while (i <= m) tmp.push_back(a[i++]);
    while (j <= r) tmp.push_back(a[j++]);
    for (int k = 0; k < (int)tmp.size(); k++) a[l + k] = tmp[k];
}
void mergeSort(vector<int>& a, int l, int r) {
    if (l >= r) return;
    int m = l + (r - l) / 2;
    mergeSort(a, l, m); mergeSort(a, m + 1, r);
    merge(a, l, m, r);
}

int partition(vector<int>& a, int l, int r) {
    int pivot = a[r], i = l;
    for (int j = l; j < r; j++)
        if (a[j] < pivot) swap(a[i++], a[j]);
    swap(a[i], a[r]);
    return i;
}
int quickselect(vector<int>& a, int l, int r, int k) {
    int p = partition(a, l, r);
    if (p == k) return a[p];
    return p < k ? quickselect(a, p+1, r, k)
                 : quickselect(a, l, p-1, k);
}

struct ListNode {
    int val;
    ListNode* next;
    ListNode(int x) : val(x), next(nullptr) {}
};

ListNode* reverse(ListNode* head) {
    ListNode* prev = nullptr;
    while (head) {
        ListNode* next = head->next;
        head->next = prev;   // rewire
        prev = head;
        head = next;
    }
    return prev;             // new head
}

bool hasCycle(ListNode* head) {
    ListNode *slow = head, *fast = head;
    while (fast && fast->next) {
        slow = slow->next;
        fast = fast->next->next;
        if (slow == fast) return true;
    }
    return false;
}

